import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第三册：培养技能 · Lesson 23 One man's meat is another man's poison","description":"学习 prefer 与 would rather，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 23 One man's meat is another man's poison","description":"学习 prefer 与 would rather，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 prefer 与 would rather，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 22 By heart","link":"/life/english/new-concept/book-3/unit-02/lesson-022"},"next":{"text":"第三册：培养技能 · Lesson 24 A skeleton in the cupboard","link":"/life/english/new-concept/book-3/unit-02/lesson-024"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 22 By heart","link":"/life/english/new-concept/book-3/unit-02/lesson-022"},"next":{"text":"第三册：培养技能 · Lesson 24 A skeleton in the cupboard","link":"/life/english/new-concept/book-3/unit-02/lesson-024"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-023.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-023.md"}`),o={name:"life/english/new-concept/book-3/unit-02/lesson-023.md"};function i(s,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第三册-培养技能-·-lesson-23-one-man-s-meat-is-another-man-s-poison" tabindex="-1">第三册：培养技能 · Lesson 23 One man&#39;s meat is another man&#39;s poison <a class="header-anchor" href="#第三册-培养技能-·-lesson-23-one-man-s-meat-is-another-man-s-poison" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 23 One man&#39;s meat is another man&#39;s poison&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>以食物偏好和文化差异练习表达喜好而不作普遍判断。某人不喜欢一种味道，并不证明食物对所有人都不好。学习 prefer 的平行结构和 would rather 的动作选择，用个人经验支持观点，同时尊重偏好与事实之间的界线。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>flavour</td><td>/ˈfleɪvə/</td><td>n.</td><td>风味</td><td>a strong flavour</td></tr><tr><td>texture</td><td>/ˈtekstʃə/</td><td>n.</td><td>口感或质地</td><td>a smooth texture</td></tr><tr><td>preference</td><td>/ˈprefrəns/</td><td>n.</td><td>偏好</td><td>personal preference</td></tr><tr><td>acquired</td><td>/əˈkwaɪəd/</td><td>adj.</td><td>后天形成的</td><td>an acquired taste</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>an acquired taste — 需要逐渐习惯才会欣赏的口味</li><li>appeal to — 对某人有吸引力</li></ul><h2 id="语法讲解-prefer-与-would-rather" tabindex="-1">语法讲解：prefer 与 would rather <a class="header-anchor" href="#语法讲解-prefer-与-would-rather" aria-label="Permalink to &quot;语法讲解：prefer 与 would rather&quot;">​</a></h2><p>prefer A to B 中 to 是介词，A 和 B 应保持结构平行，可以同为名词或动名词。prefer to do rather than do 中前半为不定式，rather than 后通常用原形。would rather 后接动词原形，否定为 would rather not do；如果后接另一个人的完整分句，常用过去式表示现在或将来的愿望。比较偏好必须明确选择对象，不要把个人喜好包装为客观优劣。prefer 通常已含比较意味，无须再加 more。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I prefer tasting a small portion to rejecting an unfamiliar dish immediately.</p></blockquote><p>我更愿意先尝一小份，而不是立刻拒绝陌生菜肴。</p><p>tasting 与 rejecting 为平行动名词结构；to 是介词而非不定式标记。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I prefer tea than coffee 应改为 prefer tea to coffee；would rather drink tea than coffee 是另一结构。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 prefer X to Y 时重读两个比较项；把 tasting 和 rejecting 的 ing 尾音读全，检查平行结构是否听得出来。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I prefer mild soup to very spicy dishes. A gentle flavour lets me notice the vegetables. My brother enjoys stronger seasoning, so we add spices at the table.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句解释一种个人饮食偏好，包含理由并承认差异。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>偏好归属于具体人物，实际安排兼顾差异。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：I would rather ___ at home.（eat/eating）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eat</p><p><strong>解析：</strong> would rather 后接原形。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>改正：She prefers reading to watch television.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> She prefers reading to watching television.</p><p><strong>解析：</strong> 两个比较项保持动名词平行。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句是否要求吃完整盘陌生菜？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> a small portion 仅表示少量尝试。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：prefer 与 would rather。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-022">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-024">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=a(o,[["render",i]]);export{u as __pageData,f as default};
